private fun drawPath02(timeMs: Int, path: Path) {
    path.reset()
    when {
        timeMs < 280 -> buildPath02_frame0(0f, path)
        timeMs <= 300 -> buildPath02_frame0((timeMs - 280) / 20f, path)
        timeMs < 300 -> buildPath02_frame1(0f, path)
        timeMs <= 320 -> buildPath02_frame1((timeMs - 300) / 20f, path)
        timeMs < 320 -> buildPath02_frame2(0f, path)
        timeMs <= 340 -> buildPath02_frame2((timeMs - 320) / 20f, path)
        timeMs < 340 -> buildPath02_frame3(0f, path)
        timeMs <= 360 -> buildPath02_frame3((timeMs - 340) / 20f, path)
        timeMs < 360 -> buildPath02_frame4(0f, path)
        timeMs <= 380 -> buildPath02_frame4((timeMs - 360) / 20f, path)
        timeMs < 380 -> buildPath02_frame5(0f, path)
        timeMs <= 400 -> buildPath02_frame5((timeMs - 380) / 20f, path)
        timeMs < 400 -> buildPath02_frame6(0f, path)
        timeMs <= 420 -> buildPath02_frame6((timeMs - 400) / 20f, path)
        timeMs < 420 -> buildPath02_frame7(0f, path)
        timeMs <= 440 -> buildPath02_frame7((timeMs - 420) / 20f, path)
        timeMs < 440 -> buildPath02_frame8(0f, path)
        timeMs <= 460 -> buildPath02_frame8((timeMs - 440) / 20f, path)
        timeMs < 460 -> buildPath02_frame9(0f, path)
        timeMs <= 480 -> buildPath02_frame9((timeMs - 460) / 20f, path)
        timeMs < 480 -> buildPath02_frame10(0f, path)
        timeMs <= 500 -> buildPath02_frame10((timeMs - 480) / 20f, path)
        timeMs < 500 -> buildPath02_frame11(0f, path)
        timeMs <= 520 -> buildPath02_frame11((timeMs - 500) / 20f, path)
        timeMs < 520 -> buildPath02_frame12(0f, path)
        timeMs <= 540 -> buildPath02_frame12((timeMs - 520) / 20f, path)
        timeMs < 540 -> buildPath02_frame13(0f, path)
