private fun drawPath03(timeMs: Int, path: Path) {
    path.reset()
    when {
        timeMs < 360 -> buildPath03_frame0(0f, path)
        timeMs <= 380 -> buildPath03_frame0((timeMs - 360) / 20f, path)
        timeMs < 380 -> buildPath03_frame1(0f, path)
        timeMs <= 400 -> buildPath03_frame1((timeMs - 380) / 20f, path)
        timeMs < 400 -> buildPath03_frame2(0f, path)
        timeMs <= 420 -> buildPath03_frame2((timeMs - 400) / 20f, path)
        timeMs < 420 -> buildPath03_frame3(0f, path)
        timeMs <= 440 -> buildPath03_frame3((timeMs - 420) / 20f, path)
        timeMs < 440 -> buildPath03_frame4(0f, path)
        timeMs <= 460 -> buildPath03_frame4((timeMs - 440) / 20f, path)
        timeMs < 460 -> buildPath03_frame5(0f, path)
        timeMs <= 480 -> buildPath03_frame5((timeMs - 460) / 20f, path)
        timeMs < 480 -> buildPath03_frame6(0f, path)
        timeMs <= 500 -> buildPath03_frame6((timeMs - 480) / 20f, path)
        timeMs < 500 -> buildPath03_frame7(0f, path)
        timeMs <= 520 -> buildPath03_frame7((timeMs - 500) / 20f, path)
        timeMs < 520 -> buildPath03_frame8(0f, path)
        timeMs <= 540 -> buildPath03_frame8((timeMs - 520) / 20f, path)
        timeMs < 540 -> buildPath03_frame9(0f, path)
        timeMs <= 560 -> buildPath03_frame9((timeMs - 540) / 20f, path)
        timeMs < 560 -> buildPath03_frame10(0f, path)
        timeMs <= 580 -> buildPath03_frame10((timeMs - 560) / 20f, path)
        timeMs < 580 -> buildPath03_frame11(0f, path)
        timeMs <= 600 -> buildPath03_frame11((timeMs - 580) / 20f, path)
        timeMs < 600 -> buildPath03_frame12(0f, path)
        timeMs <= 620 -> buildPath03_frame12((timeMs - 600) / 20f, path)
        timeMs < 620 -> buildPath03_frame13(0f, path)
        timeMs <= 640 -> buildPath03_frame13((timeMs - 620) / 20f, path)
        timeMs < 640 -> buildPath03_frame14(0f, path)
        timeMs <= 660 -> buildPath03_frame14((timeMs - 640) / 20f, path)
        timeMs < 660 -> buildPath03_frame15(0f, path)
        timeMs <= 680 -> buildPath03_frame15((timeMs - 660) / 20f, path)
        else -> buildPath03_frame15(1f, path)
    }
}

@Composable
fun AnimatedAppIcon(progress: Float, modifier: Modifier = Modifier, color: Color = Color.White) {
    // progress 0f to 1f maps to 100 to 680 ms
    val timeMs = 100 + (progress * 580).toInt()
    Canvas(modifier = modifier) {
        // viewport is 512x512
        val scaleX = size.width / 512f
        val scaleY = size.height / 512f
        val scale = minOf(scaleX, scaleY)
        drawContext.transform.scale(scale, scale, pivot = androidx.compose.ui.geometry.Offset.Zero)

        val path01 = Path()
        drawPath01(timeMs, path01)
        drawPath(path01, color = color, style = Fill)
        val path02 = Path()
        drawPath02(timeMs, path02)
        drawPath(path02, color = color, style = Fill)
        val path03 = Path()
        drawPath03(timeMs, path03)
        drawPath(path03, color = color, style = Fill)
    }
}